/*!
 * \file
 * \brief Defines the compiled Eu-152 marginal source-emission laws.
 *
 * LNHB: V. R. Vanin, R. M. de Castro and E. Browne, USP/LBNL, 2004.
 * Selected beta-minus/EC/beta-plus source emissions.
 *
 * BetaShape 2.4 (06/2024): experimental 1474.5 keV beta-minus shape;
 * calculated shapes otherwise. The retained fixint=1 run preserves
 * evaluated EC/beta-plus intensities. Conditional bin masses integrate
 * piecewise-linear reference densities; full-support references and finite
 * grids remain distinct.
 *
 * Source annihilation photons are excluded.
 *
 * Forbidden-transition Xi approximations remain nuclear-model limitations,
 * not experimentally validated shapes.
 *
 * The 485.8 keV positron branch uses bins up to 2 keV for positive-bin
 * ticket reachability; other branches use bins up to 0.5 keV.
 *
 * Physical yields remain independent emissions per parent decay. EC creates
 * no primary; daughter chains and unsupported Auger energy laws are
 * excluded.
 *
 * Selection and exclusions:
 * validation/radioactivity/data/Eu-152/reference/.
 *
 * \author Julien BERT <julien.bert@univ-brest.fr>
 * \author Didier BENOIT <didier.benoit@inserm.fr>
 */

